  /**
  * Structured reference for force fabric refresh for image.
  * @param {*} imgObj Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  function forceFabricRefreshForImage(imgObj) {
    imgObj.dirty = true
    if (typeof imgObj._setWidthHeight === "function") imgObj._setWidthHeight()
    if (typeof imgObj.setCoords === "function") imgObj.setCoords()
    if (typeof canvas.requestRenderAll === "function") canvas.requestRenderAll(); else canvas.renderAll()
  }

  /**
  * Structured reference for replace selected image in place.
  * @param {*} imgLink Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  function replaceSelectedImageInPlace(imgLink) {
    return new Promise(function (resolve) {
      let targetImgObj, id, name, clipPath, oldLeft, oldTop, oldAngle, oldFlipY, oldScaledW, oldScaledH, left, top
      targetImgObj = getTargetImageObjectForEdit()
      if (!targetImgObj) return resolve(false)
      id = targetImgObj.id
      name = targetImgObj.name
      clipPath = targetImgObj.clipPath
      oldLeft = targetImgObj.left
      oldTop = targetImgObj.top
      oldAngle = targetImgObj.angle || 0
      oldFlipY = targetImgObj.flipY
      oldScaledW = targetImgObj.getScaledWidth()
      oldScaledH = targetImgObj.getScaledHeight()
      left = parseInt(oldLeft, 10) < 0 ? 0 : oldLeft
      top = (parseInt(oldTop, 10) < 0) || (parseInt(oldTop, 10) >= 443) ? 0 : oldTop
      if (oldFlipY) {
        left = 0
        top = 0
      }
      fabric.Image.fromURL(imgLink, {
        crossOrigin: "anonymous"
      }).then(function (probeImg) {
        let ImageMode, ImageModerep, el
        ImageMode = oldScaledW > oldScaledH ? "L" : "P"
        ImageModerep = probeImg.width > probeImg.height ? "L" : "P"
        /**
        * Structured reference for apply after swap.
        * @returns {*} Value and side effects preserved from the source implementation.
        */
        function applyAfterSwap() {
          let widthFactor, heightFactor, minFactor, activeObject
          targetImgObj.set({
            id,
            name,
            left,
            top,
            angle: oldAngle,
            clipPath,
            transparentCorners: false
          })
          if ((Resizeoption === "2") && (ImageMode === ImageModerep)) {
            targetImgObj.scaleX = oldScaledW / targetImgObj.width
            targetImgObj.scaleY = oldScaledH / targetImgObj.height
          } else {
            widthFactor = oldScaledW / targetImgObj.width
            heightFactor = oldScaledH / targetImgObj.height
            minFactor = Math.min(widthFactor, heightFactor)
            targetImgObj.scale(minFactor)
          }
          forceFabricRefreshForImage(targetImgObj)
          if (isshowarray === "1") {
            activeObject = canvas.getActiveObject()
            if (activeObject) {
              activeObject.set({
                width: parseInt(activeObject.width, 10) + 1
              })
              if (typeof canvas.requestRenderAll === "function") canvas.requestRenderAll(); else canvas.renderAll()
              setTimeout(function () {
                activeObject.set({
                  width: parseInt(activeObject.width, 10)
                })
                if (typeof canvas.requestRenderAll === "function") canvas.requestRenderAll(); else canvas.renderAll()
              }, 200)
            }
          }
          setTimeout(function () {
            updateSlideThumbnail(selected_slide_id, canvas.toDataURL())
          }, 500)
          resolve(true)
        }
        if (typeof targetImgObj.setSrc === "function") {
          targetImgObj.setSrc(imgLink, {
            crossOrigin: "anonymous"
          }).then(function () {
            targetImgObj.width = targetImgObj._element ? targetImgObj._element.naturalWidth || targetImgObj._element.width : targetImgObj.width
            targetImgObj.height = targetImgObj._element ? targetImgObj._element.naturalHeight || targetImgObj._element.height : targetImgObj.height
            applyAfterSwap()
          })
          return
        }
        el = targetImgObj._element
        if (!el) return resolve(false)
        el.onload = function () {
          targetImgObj._element = el
          targetImgObj.width = el.naturalWidth || el.width
          targetImgObj.height = el.naturalHeight || el.height
          applyAfterSwap()
        }
        el.onerror = function () {
          resolve(false)
        }
        el.src = imgLink
      }, {
        crossOrigin: "anonymous"
      })
    })
  }

