  /* STAMP: Selection-aligned list markers (2026-08-17)
     When List Builder is opened for an active multi-selection, create one
     marker beside each existing object instead of generating a free-standing
     range. The original range workflow remains the fallback. */
  function addListMarkersToSelectedObjects(backColor, strokeColor, fontColor) {
    let activeSelection, selectedObjects, targets, markerType, startNumber, markerGroups
    activeSelection = canvas.getActiveObject()
    if (!activeSelection || (activeSelection.type !== "activeSelection")) {
      return false
    }
    selectedObjects = canvas.getActiveObjects().slice()
    if (!selectedObjects.length) {
      return false
    }

    /* Fabric stores child coordinates relative to an ActiveSelection.
       Release it before measuring so every marker uses the object's true
       canvas position rather than being clamped against the left edge. */
    canvas.discardActiveObject()
    selectedObjects.forEach(function (object) {
      object.setCoords()
    })
    targets = selectedObjects.map(function (object) {
      return {
        object,
        bounds: object.getBoundingRect(true, true)
      }
    }).sort(function (a, b) {
      return (a.bounds.top - b.bounds.top) || (a.bounds.left - b.bounds.left)
    })
    markerType = editorElements("#bultype").val()
    startNumber = parseInt(editorElements("#numlistrangefrom").val(), 10)
    markerGroups = []
    if (isNaN(startNumber)) {
      startNumber = 1
    }
    targets.forEach(function (target, index) {
      let markerShape, markerObjects, markerRadius, markerCenterX, markerCenterY, groupId, markerGroup
      markerObjects = []
      markerRadius = markerType === "0" ? 15 : 5
      markerCenterX = Math.max(markerRadius + 3, target.bounds.left - markerRadius - 8)
      markerCenterY = target.bounds.top + (target.bounds.height / 2)
      if (markerType === "2") {
        markerShape = new fabric.Rect({
          width: 10,
          height: 10,
          fill: backColor,
          stroke: strokeColor,
          strokeWidth: 3,
          originX: "center",
          originY: "center"
        })
      } else {
        markerShape = new fabric.Circle({
          radius: markerRadius,
          fill: backColor,
          stroke: strokeColor,
          strokeWidth: 3,
          originX: "center",
          originY: "center"
        })
      }
      if ((markerType === "0") && editorElements("#addgradnum").is(":checked")) {
        markerShape.setGradient("fill", {
          x1: markerShape.width,
          y1: 0,
          x2: 0,
          y2: markerShape.height,
          colorStops: {
            0: backColor,
            1: backColor
          }
        })
      }
      markerObjects.push(markerShape)
      if (markerType === "0") {
        markerObjects.push(new fabric.IText(String(startNumber + index), {
          fontSize: 20,
          originX: "center",
          originY: "center",
          fontFamily: "Arial",
          fill: fontColor
        }))
      }
      groupId = generate_id("g_")
      markerGroup = new fabric.Group(markerObjects, {
        id: groupId,
        left: markerCenterX,
        top: markerCenterY,
        originX: "center",
        originY: "center",
        alignmentGuideRole: "list-badge"
      })
      markerGroup.set("name", `List_${random(4)}`)
      markerGroup.setControlsVisibility({
        mt: false,
        mb: false,
        ml: false,
        mr: false,
        bl: false,
        br: false,
        tl: false,
        tr: false,
        mtr: false
      })
      pushControl(groupId, "Group")
      static_groups.push(groupId)
      anyobject++
      canvas.add(markerGroup)
      markerGroups.push(markerGroup)
    })
    canvas.setActiveObject(new fabric.ActiveSelection(selectedObjects.concat(markerGroups), {
      canvas
    }))
    canvas.requestRenderAll()
    updateCanvasState()
    setTimeout(function () {
      updateSlideThumbnail(selected_slide_id, canvas.toDataURL())
    }, 500)
    return true
  }

  /**
  * STAMP: 2026-08-18 - Merge a text-only ActiveSelection into one editable
  * textbox, optionally prefixing each source line with a list marker.
  */
  window.combineSelectedTextObjects = function (options) {
    let activeSelection, selectedRoots, selectedObjects, orderedItems, firstObject, minLeft, minTop, maxRight, markerStyle, markerMap, sourceLines, markerScale, markerLengths, lines, removedIds, combinedId, combinedFontSize, markerStyles, combinedText
    activeSelection = canvas.getActiveObject()
    selectedRoots = activeSelection && (String(activeSelection.type || "").toLowerCase() === "activeselection") ? canvas.getActiveObjects().slice() : []
    selectedObjects = []
    function collectTextObjects(item, parent) {
      if (!item) return
      if ((item.type === "text") || (item.type === "textbox") || (item.type === "i-text") || (typeof item.text === "string")) {
        selectedObjects.push({
          object: item,
          parent
        })
        return
      }
      (item._objects || []).forEach(function (child) {
        collectTextObjects(child, item)
      })
    }
    selectedRoots.forEach(function (item) {
      collectTextObjects(item, null)
    })
    if (!selectedObjects.length) return false
    canvas.discardActiveObject()
    orderedItems = selectedObjects.map(function (entry) {
      let object
      object = entry.object
      object.setCoords()
      return {
        object,
        parent: entry.parent,
        bounds: object.getBoundingRect(true, true)
      }
    }).sort(function (a, b) {
      return (a.bounds.top - b.bounds.top) || (a.bounds.left - b.bounds.left)
    })
    firstObject = orderedItems[0].object
    minLeft = Math.min.apply(null, orderedItems.map(function (item) {
      return item.bounds.left
    }))
    minTop = Math.min.apply(null, orderedItems.map(function (item) {
      return item.bounds.top
    }))
    maxRight = Math.max.apply(null, orderedItems.map(function (item) {
      return item.bounds.left + item.bounds.width
    }))
    markerStyle = options && options.markerStyle ? options.markerStyle : "numbered"
    markerMap = {
      round: "•",
      square: "▪",
      dash: "–",
      arrow: "›",
      check: "✓",
      diamond: "◆",
      "hollow-round": "○",
      "hollow-square": "□",
      triangle: "▶",
      chevron: "❯",
      "double-arrow": "⇒",
      star: "★"
    }
    sourceLines = []
    orderedItems.forEach(function (item) {
      String(item.object.text || "").split(/\r?\n/).forEach(function (line) {
        if (line.trim()) sourceLines.push({
          object: item.object,
          text: line.trim()
        })
      })
    })
    markerScale = Math.min(2, Math.max(0.5, Number(options && options.markerScale) || 1))
    markerLengths = []
    lines = sourceLines.map(function (item, index) {
      let marker
      marker = ""
      if (options && options.asList) {
        if (markerStyle === "numbered") marker = `${index + 1}.`; else if (markerStyle === "alpha") marker = `${String.fromCharCode(65 + (index % 26))}.`; else marker = markerMap[markerStyle] || "•"
      }
      markerLengths.push(marker.length)
      return (marker ? `${marker} ` : "") + item.text
    })
    selectedObjects.forEach(function (entry) {
      if (entry.parent && (typeof entry.parent.removeWithUpdate === "function")) entry.parent.removeWithUpdate(entry.object); else canvas.remove(entry.object)
    })
    removedIds = selectedObjects.map(function (entry) {
      return entry.object.id
    })
    slide_controls = (slide_controls || []).filter(function (control) {
      return removedIds.indexOf(control.id) < 0
    })
    combinedId = generate_id("textbox_")
    combinedFontSize = Math.max(8, (firstObject.fontSize || 20) * (firstObject.scaleY || 1))
    markerStyles = {}
    if (options && options.asList && (markerScale !== 1)) {
      markerLengths.forEach(function (markerLength, lineIndex) {
        let charIndex
        if (!markerLength) return
        markerStyles[lineIndex] = {}
        for (charIndex = 0; charIndex < markerLength; charIndex++) {
          markerStyles[lineIndex][charIndex] = {
            fontSize: combinedFontSize * markerScale
          }
        }
      })
    }
    combinedText = new fabric.Textbox(lines.join("\n"), {
      id: combinedId,
      left: minLeft,
      top: minTop,
      width: Math.max(120, maxRight - minLeft),
      originX: "left",
      originY: "top",
      fontFamily: firstObject.fontFamily || "Arial",
      fontSize: combinedFontSize,
      fontWeight: firstObject.fontWeight || "normal",
      fontStyle: firstObject.fontStyle || "normal",
      underline: !!firstObject.underline,
      textAlign: firstObject.textAlign || "left",
      lineHeight: firstObject.lineHeight || 1.16,
      charSpacing: firstObject.charSpacing || 0,
      fill: firstObject.fill || "#000000",
      stroke: firstObject.stroke || null,
      strokeWidth: firstObject.strokeWidth || 0,
      styles: markerStyles,
      listMarkerScale: markerScale,
      name: options && options.asList ? "Combined_List" : "Combined_Text"
    })
    pushControl(combinedId, "Textbox")
    anyobject++
    canvas.add(combinedText)
    canvas.setActiveObject(combinedText)
    combinedText.setCoords()
    canvas.requestRenderAll()
    canvas.fire("object:modified", {
      target: combinedText
    })
    updateCanvasState()
    setTimeout(function () {
      updateSlideThumbnail(selected_slide_id, canvas.toDataURL())
    }, 300)
    return true
  }
