    coords = sharedGradientDraft.coords
    editorElements("#cgGradientAngle").val(Math.round((((Math.atan2(coords.y2 - coords.y1, coords.x2 - coords.x1) * 180) / Math.PI) + 360) % 360))
    setSharedGradientVisible(Boolean(isGradient))
