  function applyTextFontWeight(target, requestedWeight) {
    let weight, targetType
    if (!target) return
    weight = String(normalizeTextFontWeight(requestedWeight))
    targetType = String(target.type || "").toLowerCase()
    if ((targetType === "group") || (targetType === "activeselection")) {
      (target._objects || []).forEach(function (item) {
        applyTextFontWeight(item, weight)
      })
      return
    }
    if ((targetType !== "textbox") && (targetType !== "i-text") && (targetType !== "text")) return
    if (target.isEditing && (target.selectionStart !== target.selectionEnd) && (typeof target.setSelectionStyles === "function")) {
      target.setSelectionStyles({
        fontWeight: weight
      }, target.selectionStart, target.selectionEnd)
    } else {
      target.set({
        fontWeight: weight
      })
      if ((typeof target.setSelectionStyles === "function") && (typeof target.text === "string")) {
        target.setSelectionStyles({
          fontWeight: weight
        }, 0, target.text.length)
      }
    }
    target.dirty = true
    target.setCoords()
  }
