  /* STAMP 2026-08-20: shared in-place reset for every object property bar. */
  propertyResetSnapshot = null
  resettablePropertyNames = ["name", "text", "styles", "fontFamily", "fontSize", "fontWeight", "fontStyle", "underline", "textAlign", "lineHeight", "charSpacing", "fill", "stroke", "strokeWidth", "backgroundColor", "textBackgroundColor", "opacity", "shadow", "rx", "ry", "radius", "scaleX", "scaleY", "skewX", "skewY", "flipX", "flipY", "cropX", "cropY", "typingEffect", "typingSpeed"]
