  slidertitleop = document.getElementById("fontsize")
  outputtitleop = document.getElementById("fontsizelabel")
  fontSizeCommitTimer = null
  /* STAMP: 2026-09-12 - Apply font size from the compact popover directly to
     the live Fabric text target. This supports selected characters, grouped
     text and ActiveSelection while debouncing expensive slide persistence. */
  function clampCanvasFontSize(value) {
    let numericValue
    numericValue = parseFloat(value)
    return Number.isFinite(numericValue) ? Math.min(200, Math.max(1, numericValue)) : null
  }
  function resolveCanvasFontSizeTarget() {
    let activeObject
    activeObject = canvas.getActiveObject()
    if (!activeObject) return null
    if ((parseInt(grpfont, 10) >= 0) && activeObject._objects) {
      return activeObject._objects[parseInt(grpfont, 10)] || activeObject
    }
    if ((isshowarray == "1") && activeObject._objects) {
      return activeObject._objects[selectedarray] || activeObject
    }
    return activeObject
  }

  /* STAMP: 2026-09-14 - Preserve an authored multiline Textbox width and its
     top-left canvas anchor when font metrics change. A visually single-line
     Textbox still grows horizontally so headings and labels do not wrap. */
  function getTextboxLayout(object) {
    let renderedLines
    if (!object || (String(object.type || "").toLowerCase() !== "textbox")) return null
    renderedLines = Array.isArray(object._textLines) ? object._textLines : []
    return {
      anchor: typeof object.getPointByOrigin === "function" ? object.getPointByOrigin("left", "top") : null,
      width: Number(object.width) || 2,
      isMultiline: (renderedLines.length > 1) || /[\r\n]/.test(String(object.text || ""))
    }
  }
  function fitTextboxToContentWidth(object, preservedLayout) {
    let layout, anchor, measuredWidth, contentWidth
    if (!object || (String(object.type || "").toLowerCase() !== "textbox")) return
    layout = preservedLayout || getTextboxLayout(object)
    anchor = layout && layout.anchor
    if (layout && layout.isMultiline) {
      object.set("width", layout.width)
      if (typeof object.initDimensions === "function") object.initDimensions()
      if (anchor && (typeof object.setPositionByOrigin === "function")) {
        object.setPositionByOrigin(anchor, "left", "top")
      }
      return
    }
    /* Measure against a temporary unconstrained width so ordinary spaces
       remain on one line; explicit newline characters are still honoured. */
    object.set("width", 100000)
    if (typeof object.initDimensions === "function") object.initDimensions()
    measuredWidth = typeof object.calcTextWidth === "function" ? object.calcTextWidth() : object.width
    contentWidth = Math.max(2, Number(object.dynamicMinWidth) || 0, Number(measuredWidth) || 0)
    object.set("width", (Math.ceil(contentWidth * 100) / 100) + 1)
    if (typeof object.initDimensions === "function") object.initDimensions()
    if (anchor && (typeof object.setPositionByOrigin === "function")) {
      object.setPositionByOrigin(anchor, "left", "top")
    }
  }
