  /**
  * STAMP: 2026-08-18 - Add editable native Fabric Polygon shapes.
  */
  function createRegularPolygonPoints(sides, outerRadius, innerRadius) {
    let points, pointCount, pointIndex, radius, angle
    points = []
    pointCount = innerRadius ? sides * 2 : sides
    for (pointIndex = 0; pointIndex < pointCount; pointIndex++) {
      radius = innerRadius && (pointIndex % 2) ? innerRadius : outerRadius
      angle = (-Math.PI / 2) + ((Math.PI * 2 * pointIndex) / pointCount)
      points.push({
        x: Math.cos(angle) * radius,
        y: Math.sin(angle) * radius
      })
    }
    return points
  }
  function addNativePolygon(sides, shapeName, innerRadius, placementPoint) {
    let safeSides, id, shape
    safeSides = Math.max(3, Math.min(12, parseInt(sides, 10) || 5))
    id = generate_id('p_')
    shape = new fabric.Polygon(createRegularPolygonPoints(safeSides, 72, innerRadius), {
      id,
      left: Math.max(20, (canvas.getWidth() - 144) / 2),
      top: Math.max(20, (canvas.getHeight() - 144) / 2),
      fill: '#000',
      stroke: '#000',
      strokeWidth: 1,
      strokeUniform: true,
      transparentCorners: false,
      selectable: true,
      evented: true,
      polygonSides: safeSides
    })
    shape.set("name", `${shapeName}_${random(4)}`)
    roundNewShapeBorder(shape)
    anyobject++
    positionShapeAtPoint(shape, placementPoint)
    canvas.add(shape)
    shape.setCoords()
    canvas.setActiveObject(shape)
    getselobjprop()
    canvas.requestRenderAll()
    updateCanvasState()
    updateSlideThumbnail(selected_slide_id, canvas.toDataURL())
    pushControl(id, shapeName)
  }
  function bindPolygonPlacement(selector, sides, shapeName, innerRadius) {
    editorElements(selector).on('click', function (event) {
      let trigger
      trigger = this
      event.preventDefault()
      setShapePlacementMode(trigger, function (point) {
        addNativePolygon(sides, shapeName, innerRadius, point)
      })
    })
  }
  bindPolygonPlacement('#pentagon', 5, 'Pentagon')
  bindPolygonPlacement('#hexagon', 6, 'Hexagon')
  bindPolygonPlacement('#octagon', 8, 'Octagon')
  bindPolygonPlacement('#diamond', 4, 'Diamond')
