  /* =========================================================================
     1) OBJECT BACKGROUND COLOR PICKER (Fill)
     -------------------------------------------------------------------------
     #fill click:
     - sets global colorMode = "shapebackfill"
     - clears hex input
     - positions and shows the shared color picker popup near the #fill element
     ========================================================================= */
  editorElements('#fill').on('click', function () {
    colorMode = "shapebackfill"
    editorElements("#hexColorInput").val("")
    positionColorPickerPopup(editorElements(this), -50, 0)
  })

  /* =========================================================================
     2) OBJECT SHADOW COLOR PICKER
     -------------------------------------------------------------------------
     #objshadowcolor click:
     - stopPropagation() prevents outer click handlers from immediately hiding popup
     - sets colorMode = "objshadow"
     - clears hex input
     - positions and shows the color picker popup
     ========================================================================= */
  editorElements('#objshadowcolor').on('click', function (e) {
    e.stopPropagation()
    colorMode = "objshadow"
    editorElements("#hexColorInput").val("")
    positionColorPickerPopup(editorElements(this), -250, -180)
  })

  /* =========================================================================
     3) OBJECT BACKGROUND COLOR PICKER (Normal state)
     -------------------------------------------------------------------------
     #objbackcolor click:
     - sets colorMode = "objback"
     - sets hover flag to 0 (normal)
     - toggles radio state UI (#rdbobjbck checked, #rdbobjstroke unchecked)
     - clears hex input
     - positions and shows the color picker popup
     ========================================================================= */
  editorElements('#objbackcolor').on('click', function () {
    colorMode = "objback"
    editorElements("#hdnobjbackstrokehover").val("0")
    editorElements("#rdbobjbck").attr('checked', true)
    editorElements("#rdbobjbck").parent().addClass("checked")
    editorElements("#rdbobjstroke").attr('checked', false)
    editorElements("#rdbobjstroke").parent().removeClass("checked")
    editorElements("#hexColorInput").val("")
    positionColorPickerPopup(editorElements(this), -250, -180)
  })

  /* =========================================================================
     4) OBJECT STROKE COLOR PICKER (Normal state)
     -------------------------------------------------------------------------
     #objstrokecolor click:
     - sets colorMode = "objstroke"
     - sets hover flag to 0 (normal)
     - toggles radio state UI (#rdbobjstroke checked, #rdbobjbck unchecked)
     - clears hex input (twice, as in your original)
     - positions and shows the color picker popup
     ========================================================================= */
  editorElements('#objstrokecolor').on('click', function () {
    colorMode = "objstroke"
    editorElements("#hdnobjbackstrokehover").val("0")
    editorElements("#rdbobjbck").attr('checked', false)
    editorElements("#rdbobjbck").parent().removeClass("checked")
    editorElements("#rdbobjstroke").attr('checked', true)
    editorElements("#rdbobjstroke").parent().addClass("checked")
    editorElements("#hexColorInput").val("")
    positionColorPickerPopup(editorElements(this), -250, -180)
    editorElements("#hexColorInput").val("")
  })

