  editorElements('.alignment').on('click', function () {
    let val, activeObject, bound
    val = editorElements(this).attr('data-action')
    activeObject = canvas.getActiveObject()
    activeObject.setOriginToCenter && activeObject.setOriginToCenter()
    bound = activeObject.getBoundingRect()
    switch (val) {
      case 'objleft':
        if (IsGroupObject == 0) {
          activeObject.set({
            left: activeObject.left - bound.left - 5
          })
        } else {
          groupedAlign("left")
        }
        break
      case 'objcenter':
        if (IsGroupObject == 0) {
          activeObject.set({
            left: canvas.width / 2
          })
        } else {
          groupedAlign("center")
        }
        break
      case 'objright':
        if (IsGroupObject == 0) {
          activeObject.set({
            left: (canvas.width - (bound.width / 2)) + 5
          })
        } else {
          groupedAlign("right")
        }
        break
      case 'objtop':
        if (IsGroupObject == 0) {
          activeObject.set({
            top: activeObject.top - bound.top - 5
          })
        } else {
          groupedAlign("top")
        }
        break
      case 'objmiddle':
        if (IsGroupObject == 0) {
          activeObject.set({
            top: canvas.height / 2
          })
        } else {
          groupedAlign("middle")
        }
        break
      case 'objbottom':
        if (IsGroupObject == 0) {
          activeObject.set({
            top: (canvas.height - (bound.height / 2)) + 5
          })
        } else {
          groupedAlign("bottom")
        }
        break
      case 'moveobjtop':
        moveSelected(Direction.UP)
        break
      case 'moveobjright':
        moveSelected(Direction.RIGHT)
        break
      case 'moveobjbottom':
        moveSelected(Direction.DOWN)
        break
      case 'moveobjleft':
        moveSelected(Direction.LEFT)
        break
    }
    activeObject.setCenterToOrigin && activeObject.setCenterToOrigin()
    activeObject.setCoords()
    canvas.renderAll()
    updateCanvasState()
  })

