  /**
  * Clone the selected object and place the copy in the editor canvas.
  * @param {*} obj Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  fnClone = function (obj) {
    let sourceObject, cloneAutomation, clonedObjectIdMap, copyData
    if (editorElements(obj).hasClass("disabled-li") == true) {
      return
    }
    sourceObject = canvas.getActiveObject()
    cloneAutomation = captureActiveObjectAutomation(sourceObject)
    clonedObjectIdMap = {}
    copyData = sourceObject.toObject()
    fabric.util.enlivenObjects([copyData]).then(function (objects) {
      objects.forEach(function (cloneObject) {
        let previousObjectId
        previousObjectId = cloneObject.id
        cloneObject.set('top', cloneObject.top + 15)
        cloneObject.set('left', cloneObject.left + 15)
        objectType = cloneObject.get('type')
        switch (objectType) {
          case 'rect':
            cloneObject.id = generate_id('r_')
            cloneObject.set("name", `Rect_${random(4)}`)
            break
          case 'circle':
            cloneObject.id = generate_id('c_')
            cloneObject.set("name", `Circle_${random(4)}`)
            break
          case 'triangle':
            cloneObject.id = generate_id('t_')
            cloneObject.set("name", `Triangle_${random(4)}`)
            break
          case 'line':
            cloneObject.id = generate_id('l_')
            cloneObject.set("name", `Line_${random(4)}`)
            break
          case 'i-text':
            cloneObject.id = generate_id('tx_')
            cloneObject.set("name", `Text_${random(4)}`)
            break
          case 'textbox':
            cloneObject.id = generate_id('textbox_')
            cloneObject.set("name", `Text_${random(4)}`)
            break
          case 'image':
            cloneObject.id = generate_id('i_')
            cloneObject.set("name", `Image_${random(4)}`)
            break
          case 'group':
            cloneObject.id = generate_id('g_')
            cloneObject.set("name", `Group_${random(4)}`)
            break
        }
        if (!cloneObject.id || (cloneObject.id === previousObjectId)) {
          cloneObject.id = generate_id(getObjectIdPrefix(objectType))
        }
        if (previousObjectId) clonedObjectIdMap[previousObjectId] = cloneObject.id
        assignFreshFabricObjectIds(cloneObject, clonedObjectIdMap, false)
        cloneObject.strokeUniform = true
        registerPastedObjectStructure(cloneObject)
        anyobject++
        cloneObject.__cgPreserveCanvasPlacement = true
        canvas.add(cloneObject)
        canvas.setActiveObject(cloneObject)
      })
      applyObjectAutomation(generated_slides[slide_index], cloneAutomation.payload, clonedObjectIdMap, false, true)
      canvas.renderAll()
      updateCanvasState()
      LoadTimeline()
    })
  }

