  /* STAMP: 2026-09-08 - Object behaviour transfer helpers.
     Animations and actions are stored on the slide rather than the Fabric
     object. These helpers keep those records aligned whenever object IDs
     change during clone, copy/paste, or cross-slide property sharing. */
  function cloneTransferValue(value) {
    return value === undefined ? undefined : JSON.parse(JSON.stringify(value))
  }
  function getTransferObjectIds(object) {
    let ids
    ids = []
    function visit(item) {
      let children
      if (!item) return
      if (item.id) ids.push(item.id)
      children = typeof item.getObjects === "function" ? item.getObjects() : item.objects
      if (Array.isArray(children)) children.forEach(visit)
    }
    if (object && (String(object.type).toLowerCase() === "activeselection")) {
      object.getObjects().forEach(visit)
    } else {
      visit(object)
    }
    return ids
  }
  function getObjectIdPrefix(type) {
    let prefixes
    prefixes = {
      rect: "r_",
      circle: "c_",
      triangle: "t_",
      polygon: "p_",
      line: "l_",
      "i-text": "tx_",
      textbox: "textbox_",
      image: "i_",
      group: "g_"
    }
    return prefixes[String(type || "").toLowerCase()] || "o_"
  }
  function assignFreshFabricObjectIds(object, idMap, includeRoot) {
    let previousId, children
    if (!object) return
    if ((includeRoot !== false) && object.id) {
      previousId = object.id
      object.id = generate_id(getObjectIdPrefix(object.type))
      idMap[previousId] = object.id
    }
    children = typeof object.getObjects === "function" ? object.getObjects() : object._objects
    if (Array.isArray(children)) {
      children.forEach(function (child) {
        assignFreshFabricObjectIds(child, idMap, true)
      })
    }
  }
  function registerPastedObjectStructure(object) {
    let children
    if (!object) return
    pushControl(object.id, object.type || "object")
    children = typeof object.getObjects === "function" ? object.getObjects() : object._objects
    if (Array.isArray(children) && (String(object.type).toLowerCase() === "group")) {
      slide_groups.push({
        groupId: object.id,
        ObjectArray: children.map(function (child) {
          return child.id
        })
      })
      children.forEach(registerPastedObjectStructure)
      generated_slides[slide_index].groups = slide_groups
    }
  }
  function remapTransferReferences(value, idMap) {
    let copy
    if (Array.isArray(value)) {
      return value.map(function (item) {
        return remapTransferReferences(item, idMap)
      })
    }
    if (value && (typeof value === "object")) {
      copy = {}
      Object.keys(value).forEach(function (key) {
        copy[key] = remapTransferReferences(value[key], idMap)
      })
      return copy
    }
    return (typeof value === "string") && idMap[value] ? idMap[value] : value
  }
  function remapTransferText(value, idMap) {
    let text
    text = String(value || "")
    Object.keys(idMap || {}).sort(function (a, b) {
      return b.length - a.length
    }).forEach(function (sourceId) {
      text = text.split(sourceId).join(idMap[sourceId])
    })
    return text
  }
  function captureObjectAutomation(slide, sourceIds, includeAll) {
    let idSet, animations, actions, loadActions, animationControls
    idSet = {};
    (sourceIds || []).forEach(function (id) {
      idSet[id] = true
    })
    animations = Array.isArray(slide && slide.AnimationSequence) ? slide.AnimationSequence : slide && slide.jsonobj && Array.isArray(slide.jsonobj.animationSequence) ? slide.jsonobj.animationSequence : []
    actions = Array.isArray(slide && slide.actions) ? slide.actions : slide && slide.jsonobj && Array.isArray(slide.jsonobj.actions) ? slide.jsonobj.actions : []
    loadActions = Array.isArray(slide && slide.loadActions) ? slide.loadActions : []
    animationControls = Array.isArray(slide && slide.animationOnControls) ? slide.animationOnControls : []
    return {
      animationSequence: cloneTransferValue(animations.filter(function (entry) {
        return includeAll || (entry && idSet[entry.objectId])
      })),
      actions: cloneTransferValue(actions.filter(function (entry) {
        return includeAll || (entry && idSet[entry.actionFrom])
      })),
      loadActions: cloneTransferValue(loadActions.filter(function (entry) {
        return includeAll || (entry && idSet[entry.actionOn])
      })),
      animationOnControls: cloneTransferValue(animationControls.filter(function (entry) {
        return includeAll || (entry && idSet[entry.id])
      }))
    }
  }
  function applyObjectAutomation(slide, payload, idMap, replaceTargetRecords, regenerateActionIds) {
    let targetIds, animationSequence, actions, loadActions, animationControls, transferredAnimations, transferredActions, transferredLoadActions, transferredControls
    if (!slide || !payload) return
    targetIds = {}
    Object.keys(idMap || {}).forEach(function (sourceId) {
      targetIds[idMap[sourceId]] = true
    })
    animationSequence = Array.isArray(slide.AnimationSequence) ? slide.AnimationSequence : []
    actions = Array.isArray(slide.actions) ? slide.actions : []
    loadActions = Array.isArray(slide.loadActions) ? slide.loadActions : []
    animationControls = Array.isArray(slide.animationOnControls) ? slide.animationOnControls : []
    if (replaceTargetRecords) {
      animationSequence = animationSequence.filter(function (entry) {
        return !entry || !targetIds[entry.objectId]
      })
      actions = actions.filter(function (entry) {
        return !entry || !targetIds[entry.actionFrom]
      })
      loadActions = loadActions.filter(function (entry) {
        return !entry || !targetIds[entry.actionOn]
      })
      animationControls = animationControls.filter(function (entry) {
        return !entry || !targetIds[entry.id]
      })
    }
    transferredAnimations = remapTransferReferences(payload.animationSequence || [], idMap)
    transferredActions = remapTransferReferences(payload.actions || [], idMap)
    transferredLoadActions = remapTransferReferences(payload.loadActions || [], idMap)
    transferredControls = remapTransferReferences(payload.animationOnControls || [], idMap)
    if (regenerateActionIds) {
      transferredActions.forEach(function (entry) {
        if (entry && entry.id) entry.id = generate_id("ca_")
      })
      transferredLoadActions.forEach(function (entry) {
        if (entry && entry.id) entry.id = generate_id("la_")
      })
    }
    slide.AnimationSequence = animationSequence.concat(transferredAnimations)
    slide.AnimationSequence.sort(function (a, b) {
      return (Number(a.order) || 0) - (Number(b.order) || 0)
    })
    slide.AnimationSequence.forEach(function (entry, index) {
      entry.order = index + 1
    })
    slide.actions = actions.concat(transferredActions)
    slide.loadActions = loadActions.concat(transferredLoadActions)
    slide.animationOnControls = animationControls.concat(transferredControls)
    if (!slide.jsonobj) slide.jsonobj = {
      objects: []
    }
    slide.jsonobj.animationSequence = cloneTransferValue(slide.AnimationSequence)
    slide.jsonobj.actions = cloneTransferValue(slide.actions)
    if (slide === generated_slides[slide_index]) {
      slide_actions = slide.actions
      slide_load_actions = slide.loadActions
      animationOnControls = slide.animationOnControls
    }
  }
  function captureActiveObjectAutomation(activeObject) {
    let slide
    slide = generated_slides[slide_index]
    return {
      sourceIds: getTransferObjectIds(activeObject),
      payload: captureObjectAutomation(slide, getTransferObjectIds(activeObject), false)
    }
  }

  /**
  * Structured reference for clone object.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  async function CloneObject() {
    let activeObject
    activeObject = canvas.getActiveObject()
    if (!activeObject) {
      notifyEditor("error", "Nothing to duplicate", "Select an object before using Duplicate.")
      return
    }
    slideact = "Same"
    _clipboard = await activeObject.clone()
    clipboardObjectAutomation = captureActiveObjectAutomation(activeObject)
    await Paste()
  }

  /**
  * Structured reference for copy active object.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  async function CopyActiveObject() {
    let activeObject
    activeObject = canvas.getActiveObject()
    if (!activeObject) {
      notifyEditor("error", "Nothing to copy", "Select an object before using Copy.")
      return
    }
    slideact = "Same"
    _clipboard = await activeObject.clone()
    clipboardObjectAutomation = captureActiveObjectAutomation(activeObject)
  }

  /**
  * Structured reference for paste.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  async function Paste() {
    let clonedObj, pastedObjectIdMap, clonedChildren, clonedTransforms, pastedSelection, objectType, previousObjectId
    if (!_clipboard) {
      notifyEditor("error", "Nothing to paste", "Copy an object before using Paste.")
      return
    }
    clonedObj = await _clipboard.clone()
    pastedObjectIdMap = {}
    canvas.discardActiveObject()
    if (String(clonedObj.type).toLowerCase() === 'activeselection') {
      /* STAMP: 2026-09-01 - Detach cloned selection children using
         their world transforms before adding them to the active slide. */
      clonedObj.canvas = canvas
      clonedChildren = clonedObj.getObjects().slice()
      clonedTransforms = clonedChildren.map(function (obj) {
        return obj.calcTransformMatrix()
      })
      clonedChildren.forEach(function (obj, childIndex) {
        let objectType, previousObjectId
        fabric.util.applyTransformToObject(obj, clonedTransforms[childIndex])
        obj.group = null
        objectType = obj.get('type')
        previousObjectId = obj.id
        switch (objectType) {
          case 'rect':
            obj.id = generate_id('r_')
            break
          case 'circle':
            obj.id = generate_id('c_')
            break
          case 'triangle':
            obj.id = generate_id('t_')
            break
          case 'line':
            obj.id = generate_id('l_')
            break
          case 'i-text':
            obj.id = generate_id('tx_')
            break
          case 'textbox':
            obj.id = generate_id('textbox_')
            break
          case 'image':
            obj.id = generate_id('i_')
            break
          case 'group':
            obj.id = generate_id('g_')
            break
        }
        if (!obj.id || (obj.id === previousObjectId)) {
          obj.id = generate_id(getObjectIdPrefix(objectType))
        }
        if (previousObjectId) pastedObjectIdMap[previousObjectId] = obj.id
        assignFreshFabricObjectIds(obj, pastedObjectIdMap, false)
        if (slideact == "Same") {
          obj.set('top', obj.top + 20)
          obj.set('left', obj.left + 20)
        } else {
          obj.set('top', obj.top)
          obj.set('left', obj.left)
        }
        obj.strokeUniform = true
        registerPastedObjectStructure(obj)
        anyobject++
        obj.__cgPreserveCanvasPlacement = true
        canvas.add(obj)
        canvas.renderAll()
        updateCanvasState()
      })
      pastedSelection = new fabric.ActiveSelection(clonedChildren, {
        canvas
      })
      canvas.setActiveObject(pastedSelection)
      pastedSelection.setCoords()
      canvas.requestRenderAll()
      updateCanvasState()
      notifyEditor("success", "Objects pasted", `${clonedChildren.length} objects were added to the canvas.`)
    } else {
      objectType = clonedObj.get('type')
      previousObjectId = clonedObj.id
      switch (objectType) {
        case 'rect':
          clonedObj.id = generate_id('r_')
          clonedObj.set("name", `Rect_${random(4)}`)
          break
        case 'circle':
          clonedObj.id = generate_id('c_')
          clonedObj.set("name", `Circle_${random(4)}`)
          break
        case 'triangle':
          clonedObj.id = generate_id('t_')
          clonedObj.set("name", `Triangle_${random(4)}`)
          break
        case 'line':
          clonedObj.id = generate_id('l_')
          clonedObj.set("name", `Line_${random(4)}`)
          break
        case 'i-text':
          clonedObj.id = generate_id('tx_')
          clonedObj.set("name", `Text_${random(4)}`)
          break
        case 'textbox':
          clonedObj.id = generate_id('textbox_')
          clonedObj.set("name", `Text_${random(4)}`)
          break
        case 'image':
          clonedObj.id = generate_id('i_')
          clonedObj.set("name", `Image_${random(4)}`)
          break
        case 'group':
          clonedObj.id = generate_id('g_')
          clonedObj.set("name", `Group_${random(4)}`)
          break
      }
      if (!clonedObj.id || (clonedObj.id === previousObjectId)) {
        clonedObj.id = generate_id(getObjectIdPrefix(objectType))
      }
      if (previousObjectId) pastedObjectIdMap[previousObjectId] = clonedObj.id
      assignFreshFabricObjectIds(clonedObj, pastedObjectIdMap, false)
      if (slideact == "Same") {
        clonedObj.set('top', clonedObj.top + clonedObj.height + 20)
        clonedObj.set('left', clonedObj.left)
      } else {
        clonedObj.set('top', clonedObj.top)
        clonedObj.set('left', clonedObj.left)
      }
      clonedObj.strokeUniform = true
      registerPastedObjectStructure(clonedObj)
      anyobject++
      clonedObj.__cgPreserveCanvasPlacement = true
      canvas.add(clonedObj)
      canvas.setActiveObject(clonedObj)
      canvas.renderAll()
      updateCanvasState()
      canvas.setActiveObject(clonedObj)
    }
    if (clipboardObjectAutomation) {
      applyObjectAutomation(generated_slides[slide_index], clipboardObjectAutomation.payload, pastedObjectIdMap, false, true)
      updateCanvasState()
      LoadTimeline()
    }
    getselobjprop()
  }

