  /**
  * Structured reference for select all canvas objects.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  function selectAllCanvasObjects() {
    let canvasObjects, selection
    canvasObjects = canvas.getObjects().filter(function (object) {
      return object && (object.visible !== false)
    })
    if (!canvasObjects.length) return false
    canvas.discardActiveObject()
    selection = canvasObjects.length === 1 ? canvasObjects[0] : new fabric.ActiveSelection(canvasObjects, {
      canvas
    })
    canvas.setActiveObject(selection)
    canvas.requestRenderAll()
    return true
  }
