  /* STAMP: 2026-08-27 - The legacy delete overlay previously used abrupt
     show/hide calls. Centralized fades preserve its fixed geometry and
     prevent visual jumping across object and action deletion flows. */
  function showDeletePrompt() {
    editorElements("#popupDelete").stop(true, true).fadeIn(180)
  }
  function hideDeletePrompt() {
    editorElements("#popupDelete").stop(true, true).fadeOut(160)
  }
  editorElements("#removeactn").on('click', function () {
    editorElements('#delhypaction').click()
    editorElements('#delanimaction').click()
    editorElements('#delslideaction').click()
    hideDeletePrompt()
    editorElements(".addclickactn").show()
    editorElements('.addclickactn').attr('onclick', 'addClickAction()').html('Add')
    editorElements(".addloadactn").show()
    editorElements('.addloadactn').attr('onclick', 'addLoadAction()').html('Add')
  })
  function performDeleteSelectedObjects() {
    let activeObjects, objects, deletedCount
    canvas.isDrawingMode = false
    activeObjects = canvas.getActiveObject()
    if (!activeObjects) {
      safeHideModal("deleteObjectModal")
      return
    }
    deletedCount = activeObjects._objects && (activeObjects.type !== "group") ? activeObjects._objects.length : 1
    if (activeObjects._objects && (activeObjects.type !== "group")) {
      objects = canvas.getActiveObject()
      objects._objects.forEach(function (object, key) {
        for (i = 0; i < ids.length; i++) {
          if (object.id === ids[i]) {
            ids.splice(i, 1)
            popControl(object.id)
          }
        }
        canvas.remove(object)
      })
      canvas.discardActiveObject()
      canvas.renderAll()
      updateCanvasState()
    } else {
      ids = filterEditorEntries(ids, function (value) {
        return value !== canvas.getActiveObject().id
      })
      popControl(canvas.getActiveObject().id)
      canvas.remove(canvas.getActiveObject())
    }
    LoadTimeline()
    canvas.requestRenderAll()
    editorElements("#addshadow").show()
    editorElements("#addshadow").html("Add")
    editorElements(".addclickactn").show()
    editorElements('.addclickactn').attr('onclick', 'addClickAction()').html('Add')
    editorElements(".addloadactn").show()
    editorElements('.addloadactn').attr('onclick', 'addLoadAction()').html('Add')
    hideDeletePrompt()
    safeHideModal("deleteObjectModal")
    notifyEditor("removed", deletedCount > 1 ? `${deletedCount} objects deleted` : "Object deleted", "The selected canvas content was removed.")
  }

  /* Legacy preference remains readable for stored profiles, but object deletion
     now always confirms per the 2026-09-29 destructive-action contract. */
  SKIP_OBJECT_DELETE_CONFIRMATION_KEY = "content-generator-skip-object-delete-confirmation-v1"
  function shouldSkipObjectDeleteConfirmation() {
    try {
      return window.localStorage.getItem(SKIP_OBJECT_DELETE_CONFIRMATION_KEY) === "true"
    } catch (error) {
      return false
    }
  }
  editorElements("#skipObjectDeleteConfirmation").prop("checked", shouldSkipObjectDeleteConfirmation()).on("change", function () {
    try {
      if (this.checked) {
        window.localStorage.setItem(SKIP_OBJECT_DELETE_CONFIRMATION_KEY, "true")
      } else {
        window.localStorage.removeItem(SKIP_OBJECT_DELETE_CONFIRMATION_KEY)
      }
    } catch (error) {
      console.warn("Object delete confirmation preference could not be saved", error)
    }
  })
  requestDeleteSelectedObjects = function () {
    let activeObject, activeGroup
    activeObject = canvas.getActiveObject()
    activeGroup = canvas.getActiveObjects()
    if (!activeObject && (!activeGroup || (activeGroup.length === 0))) {
      return false
    }
    safeShowModal("deleteObjectModal", "Are you sure you want to delete the selected object?")
    return false
  }
  editorElements("#DeleteSelected").on('click', performDeleteSelectedObjects)
  editorElements("#confirmDeleteObject").on('click', performDeleteSelectedObjects)
  editorElements("#DeleteSelectedno").on('click', function () {
    hideDeletePrompt()
  })
  editorElements("#popupDeleteClose").on("click", hideDeletePrompt)
  editorElements(document).on("keydown", function (e) {
    let ekeyCode, keyboardTarget, isEditableTarget, activeTextObject, isEditingCanvasText, activeObject, activeGroup, objectlenght, type, historyModifier, clipboardModifier
    ekeyCode = e.keyCode
    keyboardTarget = e.target
    isEditableTarget = keyboardTarget && (/^(INPUT|TEXTAREA|SELECT)$/.test(keyboardTarget.tagName) || keyboardTarget.isContentEditable)
    activeTextObject = canvas.getActiveObject()
    isEditingCanvasText = activeTextObject && ((activeTextObject.type === "textbox") || (activeTextObject.type === "i-text")) && activeTextObject.isEditing
    /* STAMP: 2026-09-14 - Route the general canvas-surface shortcut
     * through Fabric's authoritative keyboard lifecycle. This keeps the
     * command independent of object selection while protecting form fields
     * and active text editing from an accidental Shift+G toggle. */
    if (!isEditingCanvasText && window.CGGeneralShortcuts && (typeof window.CGGeneralShortcuts.handleKeydown === "function") && window.CGGeneralShortcuts.handleKeydown(e)) {
      return
    }
    if (ekeyCode == 16) {
      editorElements("#shifton").val("1")
    }
    if (ekeyCode == 17) {
      editorElements("#ctrlon").val("1")
      ctrl = 1
    }
    if (ekeyCode == 46) {
      canvas.isDrawingMode = false
      activeObject = canvas.getActiveObject()
      activeGroup = canvas.getActiveObjects()
      if (!activeObject || !activeGroup || (activeGroup.length === 0)) {
        return
      }
      type = activeObject.type
      if ((type == "textbox") || (type == "i-text")) {
        if (!activeObject.isEditing) {
          objectlenght = 0
        } else {
          objectlenght = 1
        }
      } else {
        objectlenght = 0
      }
      if ((activeGroup.length > 0) && (objectlenght == 0)) {
        if (hdnincanvas == '1') {
          requestDeleteSelectedObjects()
        }
      }
    }
    if (ekeyCode == 37) {
      if (hdnincanvas == "1") {
        moveSelected(Direction.LEFT)
      }
    }
    if (ekeyCode == 38) {
      if (hdnincanvas == "1") {
        event.view.event.preventDefault()
        moveSelected(Direction.UP)
      } else {
        if (editorElements("#shifton").val() == "1") {
          checkFocus("BigPlus")
        } else {
          checkFocus("Plus")
        }
      }
    }
    if (ekeyCode == 39) {
      if (hdnincanvas == "1") {
        moveSelected(Direction.RIGHT)
      }
    }
    if (ekeyCode == 40) {
      if (hdnincanvas == "1") {
        event.view.event.preventDefault()
        moveSelected(Direction.DOWN)
      } else {
        if (editorElements("#shifton").val() == "1") {
          checkFocus("BigMinus")
        } else {
          checkFocus("Minus")
        }
      }
    }
    historyModifier = (ctrl == 1) || e.ctrlKey || e.metaKey
    if ((ekeyCode == 89) && historyModifier) {
      e.preventDefault()
      editorElements('#redo').click()
    }
    if ((ekeyCode == 90) && historyModifier) {
      e.preventDefault()
      if (e.shiftKey) editorElements('#redo').click(); else editorElements('#undo').click()
    }
    if (ekeyCode == 190) { }
    if ((ekeyCode == 27) && (hdnincanvas == "1") && !isEditableTarget && !isEditingCanvasText) {
      e.preventDefault()
      ResetCanvasObjects()
    }
    clipboardModifier = e.ctrlKey || e.metaKey
    /* STAMP: 2026-09-10 - Canvas-scoped Select All mirrors the visible
     * multiselect action without hijacking form fields or text editing. */
    if (clipboardModifier && (ekeyCode == 65) && (hdnincanvas == "1") && !isEditableTarget && !isEditingCanvasText) {
      e.preventDefault()
      selectAllCanvasObjects()
    }
    if (clipboardModifier && (e.which == cKey) && (hdnincanvas == "1") && !isEditableTarget && !isEditingCanvasText) {
      e.preventDefault()
      CopyActiveObject()
    }
    if (clipboardModifier && (e.which == vKey) && !isEditableTarget && !isEditingCanvasText) {
      activeObject = canvas.getActiveObject()
      if ((activeObject == null) && (hdnincanvas == "1")) {
        e.preventDefault()
        Paste()
      } else if (!activeObject.isEditing && (hdnincanvas == "1")) {
        e.preventDefault()
        Paste()
      }
    }
  })
  editorElements(document).on("keyup", function (e) {
    let ekeyCode, keyboardTarget, activeTextObject, isEditingCanvasText, isEditableTarget
    ekeyCode = e.keyCode
    if (ekeyCode == 16) {
      editorElements("#shifton").val("0")
    }
    if (ekeyCode == 17) {
      editorElements("#ctrlon").val("0")
      ctrl = 0
    }
    keyboardTarget = e.target
    activeTextObject = canvas.getActiveObject()
    isEditingCanvasText = activeTextObject && ((activeTextObject.type === "textbox") || (activeTextObject.type === "i-text")) && activeTextObject.isEditing
    isEditableTarget = keyboardTarget && (/^(INPUT|TEXTAREA|SELECT)$/.test(keyboardTarget.tagName) || keyboardTarget.isContentEditable)
    if ((ekeyCode == 27) && (hdnincanvas == "1") && !isEditableTarget && !isEditingCanvasText) {
      ResetCanvasObjects()
    }
  })

  /* STAMP: 2026-08-18 - Awaited, slide-scoped Fabric 7 history navigation. */
  function moveCanvasHistory(direction) {
    let history, targetIndex, historySlideId
    history = getSlideHistory(selected_slide_id)
    if ((direction < 0) && history && (history.currentStateIndex === (history.canvasState.length - 1))) {
      updateCanvasState()
      history = getSlideHistory(selected_slide_id)
    }
    targetIndex = history ? history.currentStateIndex + direction : -1
    if (ruConfig.isRestoring || !history || (targetIndex < 0) || (targetIndex >= history.canvasState.length)) {
      refreshUndoRedoButtons(selected_slide_id)
      return Promise.resolve(false)
    }
    historySlideId = selected_slide_id
    ruConfig.undoFinishedStatus = 0
    ruConfig.redoFinishedStatus = 0
    ruConfig.undoStatus = direction < 0
    ruConfig.redoStatus = direction > 0
    ruConfig.isRestoring = true
    refreshUndoRedoButtons(historySlideId)
    return loadCanvasStateSnapshot(history.canvasState[targetIndex]).then(function (restored) {
      if (!restored || (selected_slide_id !== historySlideId)) return false
      history.canvasState[targetIndex] = getCanvasStateSnapshot()
      history.currentStateIndex = targetIndex
      persistActiveSlideState()
      updateSlideThumbnail(historySlideId, canvas.toDataURL())
      return true
    }).finally(function () {
      ruConfig.undoStatus = false
      ruConfig.redoStatus = false
      ruConfig.undoFinishedStatus = 1
      ruConfig.redoFinishedStatus = 1
      refreshUndoRedoButtons(selected_slide_id)
    })
  }
  editorElements('#undo').off('click.cgHistory').on('click.cgHistory', function (event) {
    event.preventDefault()
    moveCanvasHistory(-1)
  })
  editorElements('#redo').off('click.cgHistory').on('click.cgHistory', function (event) {
    event.preventDefault()
    moveCanvasHistory(1)
  })
