  const updateSlideSettings = (paginate, navigate) => {
    generated_slides.forEach(slide => {
      slide.ShowPaginate = paginate
      slide.ShowNavigate = navigate
    })
    ShowPaginate = paginate
    ShowNavigate = navigate
  }
