  editorElements("#ungroup").on('click', function () {
    let activeObject, childWorldTransforms, items, i, objectType, temp_id
    if (editorElements(obj).hasClass("disabled-li") === true) {
      return
    }
    activeObject = canvas.getActiveObject()
    if (activeObject.type === "group") {
      if (static_groups.includes(activeObject.id)) {
        return
      }
      /* STAMP: 2026-08-31 - Capture every child's complete canvas-space
         transform before detaching it so ungroup never changes placement. */
      childWorldTransforms = activeObject._objects.map(function (item) {
        return item.calcTransformMatrix()
      })
      items = activeObject.removeAll()
      items.forEach(function (item, itemIndex) {
        fabric.util.applyTransformToObject(item, childWorldTransforms[itemIndex])
        item.setCoords()
      })
      canvas.remove(activeObject)
      for (i = 0; i < items.length; i++) {
        objectType = items[i].type
        anyobject++
        items[i].__cgPreserveCanvasPlacement = true
        canvas.add(items[i])
        canvas.item(canvas.size() - 1).hasControls = true
        temp_id = items[i].id
        pushControl(temp_id, objectType)
      }
      canvas.renderAll()
      updateCanvasState()
      popControl(activeObject.id)
      notifyEditor("success", "Objects ungrouped", `${items.length} objects are now editable separately.`)
    }
  })

