  /* Modern slide-video event binding stamped 2026-04-23:
     replace the older duplicated paste/save handlers with one normalized flow
     while preserving the same slide model and canvas update behavior. */
  function renderSlideVideoPreview(rawValue, options) {
    let val, previewTitle, providerBadge, settings, isSavedVideo, details
    val = (rawValue || "").trim()
    previewTitle = document.getElementById("sld-video-preview-title")
    providerBadge = document.getElementById("sld-video-provider-badge")
    settings = options || {}
    isSavedVideo = typeof settings.isSavedVideo === "boolean" ? settings.isSavedVideo : currentSlideHasEmbeddedVideo()
    if (!val) {
      editorElements("#sld-video-preview-inner").empty()
      editorElements("#txtsldvideoembedlink").val("").removeData("normalizedIframe")
      if (previewTitle) {
        previewTitle.textContent = "Embed Preview"
      }
      if (providerBadge) {
        providerBadge.textContent = "Video"
      }
      setSlideVideoStatus("Ready for a YouTube/Vimeo link or iframe embed.", "")
      syncSlideVideoActionState("input", false)
      return
    }
    details = getVideoEmbedDetails(val)
    if (!details) {
      editorElements("#sld-video-preview-inner").empty()
      editorElements("#txtsldvideoembedlink").removeData("normalizedIframe")
      if (previewTitle) {
        previewTitle.textContent = "Embed Preview"
      }
      if (providerBadge) {
        providerBadge.textContent = "Video"
      }
      setSlideVideoStatus("Paste a valid YouTube/Vimeo link or iframe embed to continue.", "error")
      syncSlideVideoActionState("input", false)
      if (settings.showInvalidModal) {
        showInvalidIframeModal()
      }
      return
    }
    editorElements("#txtsldvideoembedlink").val(val).data("normalizedIframe", details.iframeHtml)
    editorElements("#sld-video-preview-inner").html(details.iframeHtml)
    if (previewTitle) {
      previewTitle.textContent = `${details.provider} Preview`
    }
    if (providerBadge) {
      providerBadge.textContent = details.provider
    }
    if (isSavedVideo) {
      setSlideVideoStatus(`${details.provider} video is added. Use Replace or Remove.`, "ready")
      syncSlideVideoActionState("preview-saved", true)
      return
    }
    setSlideVideoStatus(`${details.provider} preview is ready. Use Add to save it.`, "ready")
    syncSlideVideoActionState("preview-pending", false)
  }
  editorElements("#confirmInvalidIframe").off("click").on("click", function () {
    editorElements("#txtsldvideoembedlink").val("")
    renderSlideVideoPreview("")
    safeHideModal("invalidIframeModal")
  })
  editorElements("#txtsldvideoembedlink").off("input paste")
  editorElements("#txtsldvideoembedlink").on("input", function () {
    renderSlideVideoPreview(editorElements(this).val())
  })
  editorElements("#txtsldvideoembedlink").on("paste", function () {
    let textarea
    textarea = this
    setTimeout(function () {
      renderSlideVideoPreview(editorElements(textarea).val())
    }, 50)
  })
  editorElements("#repsldvideoembd").off("click").on("click", function () {
    let currentValue
    currentValue = editorElements("#txtsldvideoembedlink").val()
    setSlideVideoStatus("Update the link or iframe, then preview will appear again.", "")
    syncSlideVideoActionState("input", currentSlideHasEmbeddedVideo())
    editorElements("#txtsldvideoembedlink").val(currentValue).trigger("focus")
  })
  editorElements("#Addsldvideoembd").off("click").on("click", function () {
    let details, url
    details = getVideoEmbedDetails(editorElements("#txtsldvideoembedlink").val())
    if (!details) {
      renderSlideVideoPreview(editorElements("#txtsldvideoembedlink").val(), {
        showInvalidModal: true
      })
      return
    }
    loadVideoPageJsonOnCanvas()
    url = details.iframeHtml.replace("<iframe", "<iframe id='ifembvideoexport'")
    generated_slides[slide_index].SlideVideo = url
    refreshSlideMediaIndicators(generated_slides[slide_index].id)
    editorElements("#txtsldvideoembedlink").val(details.iframeHtml)
    renderSlideVideoPreview(details.iframeHtml, {
      isSavedVideo: true
    })
  })
  editorElements("#delsldvideoembd").off("click").on("click", function () {
    if (!currentSlideHasEmbeddedVideo()) {
      editorElements("#txtsldvideoembedlink").val("")
      renderSlideVideoPreview("")
      return
    }
    safeShowModal("modalRemoveVideo", "Unable to open remove video confirmation.")
  })
  editorElements("#confirmRemoveVideo").off("click").on("click", function () {
    safeHideModal("modalRemoveVideo")
    removeVideoFromCanvas()
    editorElements("#txtsldvideoembedlink").val("")
    renderSlideVideoPreview("")
  })
  renderSlideVideoPreview(editorElements("#txtsldvideoembedlink").val(), {
    isSavedVideo: currentSlideHasEmbeddedVideo()
  })

  /**
  * Read the current slide HTML payload saved in the generated slide record.
  * @returns {string} Slide HTML content or an empty string when not set.
  */
  function getCurrentSlideHtmlContent() {
    if (!generated_slides || !generated_slides[slide_index]) {
      return ""
    }
    return typeof generated_slides[slide_index].HTMlcontent === "string" ? generated_slides[slide_index].HTMlcontent : ""
  }

  /**
  * Initialize the slide HTML Summernote editor once so the modal offers the
  * same visual/code workflow expected from a full HTML editor.
  */
  function ensureHtmlContentEditorInitialized() {
    let editorEditor, editorHeight
    editorEditor = editorElements("#txtHtmlContent")
    if (!editorEditor.length || editorEditor.data("cgHtmlEditorReady")) {
      return editorEditor
    }
    editorHeight = Math.max(480, window.innerHeight - 250)
    editorEditor.summernote({
      placeholder: "Paste HTML markup here...",
      height: editorHeight,
      dialogsInBody: true,
      toolbar: [["style", ["style"]], ["font", ["bold", "italic", "underline", "clear"]], ["para", ["ul", "ol", "paragraph"]], ["insert", ["link", "table", "hr"]], ["view", ["codeview"]]],
      callbacks: {
        onChange(contents) {
          if (editorElements("#html-preview-panel").hasClass("active")) {
            renderHtmlContentPreview(contents)
          }
        }
      }
    })
    editorEditor.data("cgHtmlEditorReady", true)
    return editorEditor
  }

  /**
  * Read the current HTML editor payload regardless of whether Summernote has
  * already been initialized for this modal session.
  * @returns {string} Current HTML editor contents.
  */
  function getHtmlContentEditorValue() {
    let editorEditor
    editorEditor = editorElements("#txtHtmlContent")
    if (editorEditor.data("cgHtmlEditorReady")) {
      return editorEditor.summernote("code")
    }
    return editorEditor.val() || ""
  }

  /**
  * Set the HTML editor payload while keeping both the Summernote instance and
  * the underlying textarea synchronized.
  * @param {string} htmlValue - HTML content to inject into the editor.
  */
  function setHtmlContentEditorValue(htmlValue) {
    let normalizedHtml, editorEditor
    normalizedHtml = typeof htmlValue === "string" ? htmlValue : ""
    editorEditor = ensureHtmlContentEditorInitialized()
    if (editorEditor.data("cgHtmlEditorReady")) {
      editorEditor.summernote("code", normalizedHtml)
    } else {
      editorEditor.val(normalizedHtml)
    }
  }

  /**
  * Render the HTML preview inside a sandboxed iframe so pasted markup can be
  * inspected safely before it is committed to slide JSON.
  * @param {string} rawHtml - Raw HTML content entered by the user.
  */
  function renderHtmlContentPreview(rawHtml) {
    let previewFrame, previewStatus, htmlValue
    previewFrame = document.getElementById("htmlContentPreviewFrame")
    previewStatus = document.getElementById("htmlPreviewStatus")
    htmlValue = typeof rawHtml === "string" ? rawHtml : ""
    if (!previewFrame || !previewStatus) {
      return
    }
    if (!htmlValue.trim()) {
      previewFrame.srcdoc = "<!doctype html><html><body style='margin:0;padding:24px;font-family:Segoe UI,Arial,sans-serif;color:#64748b;background:#f8fafc;'>Add HTML in Code View to preview it here.</body></html>"
      previewStatus.textContent = "Add HTML in Code View to preview it here."
      return
    }
    previewFrame.srcdoc = buildScriptFreeHtmlPreview(htmlValue)
    previewStatus.textContent = "Sandboxed preview of the current HTML content."
  }

  /**
  * Load the current slide HTML into the modal controls before the modal opens.
  */
  function syncHtmlContentModalFromSlide() {
    let htmlValue
    htmlValue = getCurrentSlideHtmlContent()
    setHtmlContentEditorValue(htmlValue)
    renderHtmlContentPreview(htmlValue)
  }
  editorElements("#openHtmlContentModal").on("click", function (e) {
    let codeTab
    e.preventDefault()
    ensureHtmlContentEditorInitialized()
    syncHtmlContentModalFromSlide()
    codeTab = document.getElementById("html-code-tab")
    if (codeTab && window.bootstrap && (typeof window.bootstrap.Tab === "function")) {
      window.bootstrap.Tab.getOrCreateInstance(codeTab).show()
    }
    safeShowModal("htmlContentModal", "Unable to open HTML content editor.")
  })
  editorElements("#html-preview-tab").on("shown.bs.tab", function () {
    renderHtmlContentPreview(getHtmlContentEditorValue())
  })
  editorElements("#clearHtmlContentBtn").on("click", function () {
    setHtmlContentEditorValue("")
    renderHtmlContentPreview("")
  })
  editorElements("#saveHtmlContentBtn").on("click", function () {
    if (!generated_slides || !generated_slides[slide_index]) {
      return
    }
    generated_slides[slide_index].HTMlcontent = getHtmlContentEditorValue()
    renderHtmlContentPreview(generated_slides[slide_index].HTMlcontent)
    safeHideModal("htmlContentModal")
  })

