  /* =============================================================================
     8) SLIDE AUDIO UPLOAD (uploadaudio + chkplayonce)
  ============================================================================= */
  document.getElementById('uploadaudio').addEventListener("change", function (e) {
    const file = this.files[0]
    if (!file) return
    if ((editorElements("#slideMediaModal").data("mediaType") === "audio") && editorElements("#slideMediaModal").hasClass("show")) {
      prepareSlideAudioOptimization(file)
      e.preventDefault()
      return
    }
    slideAudioMime = file.type
    audioToBase64(file).then(base64 => {
      slideAudioBase64 = base64
      Audiobase64(base64)
      editorElements("#audioPreviewArea").show()
    })
    e.preventDefault()
    editorElements("#divmanageslideaud").hide()
  })

