  /**
  * You had TWO `var vid = document.createElement('video');` declarations.
  * Keeping ONLY ONE to avoid redeclare noise, but using the SAME variable name.
  */
  vid = document.createElement('video')
  /**
  * Audio effect upload:
  * - Create object URL and load into <video> to read duration
  * - Upload via FormData to EffectAudioUpload.ashx
  * - Update UI + hidden duration field + timeline refresh if replace
  */
  document.querySelector('#uploadaudioeff').addEventListener('change', function (e) {
    let fileURL
    fileURL = URL.createObjectURL(this.files[0])
    vid.src = fileURL
    vid.ondurationchange = function () {
      let fileUpload, files, data, activeObject, ActiveObjId, i, file
      fileUpload = editorElements("#uploadaudioeff").get(0)
      files = fileUpload.files
      data = new FormData()
      activeObject = canvas.getActiveObject()
      ActiveObjId = activeObject.id
      for (i = 0; i < files.length; i++) {
        file = document.getElementById("uploadaudioeff").files[i]
        data.append("FileUpload", file)
        data.append("FileName", ActiveObjId)
      }
      showLoadingWrapper(true)
      requestEditorResource({
        url: "ajax/EffectAudioUpload.ashx",
        type: "POST",
        data,
        contentType: false,
        processData: false,
        success(result) {
          editorElements("#uploadaudioeff").val("")
          editorElements("#effaudiolink").val(`../../CanvasJS/Pages/${result}`)
          editorElements("#getaudeff").show()
          editorElements("#getaudeff").attr("src", `../../CanvasJS/Pages/${result}?v=${random(2)}`)
          editorElements("#divaudeff").hide()
          editorElements('#addloadactn').show()
          editorElements("#ldactnprop").show()
          editorElements("#diveffdur").hide()
          showLoadingWrapper(false)
          editorElements("#repeffaud").show()
          editorElements(`#hdnaud_${activeObject}`).val(vid.duration)
          if (isReplace == 1) {
            LoadTimeline()
          }
        },
        error(err) {
          showLoadingWrapper(false)
        }
      })
    }
  })

