  /**
  * Rebuild the slide or control dropdown list from the latest editor state.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  updateDropdownList = function () {
    editorElements('.scrollableList').remove()
    editorElements('.makeMeList').each(function (index, element) {
      let CurrContrlID
      CurrContrlID = editorElements(this).attr("id")
      if (editorElements(this).hasClass('hidden')) {
        editorElements('.effectFromWrapper').hide()
      }
      editorElements(this).parent().after().append("<div class='scrollableList'><div class='selectedOption'></div><ul></ul></div>")
      editorElements(element).each(function (idx, elm) {
        editorElements('option', elm).each(function (id, el) {
          let fnMouseOver, obj
          fnMouseOver = (editorElements(element).data('hover') == "1") && el.value ? `highlightObject('${el.value}')` : ''
          if (activeslide != el.value) {
            if (el.text == "Slide 0") {
              el.text = "Slide 1"
            }
            if (CurrContrlID == "sel_control") {
              if (el.value.includes("textbox_") || el.value.includes("g_")) {
                id = el.value
                obj = canvas.getObjectById(id)
                if (obj != undefined) {
                  editorElements('.scrollableList ul:last').append(`<li  id="li_${el.value}" data-value="${el.value}" onmouseover="${fnMouseOver}"><a id="a_${el.value}" style="color:#000 !important" onclick="Selamin(this.id)">${el.text}</a></li>`)
                }
              }
            } else {
              editorElements('.scrollableList ul:last').append(`<li  id="li_${el.value}" data-value="${el.value}" onmouseover="${fnMouseOver}"><a id="a_${el.value}" style="color:#000 !important" onclick="Selamin(this.id)">${el.text}</a></li>`)
            }
          }
        })
        editorElements('.scrollableList ul').hide()
        editorElements('.makeMeUl').children('div.selectedOption').text("Select")
      })
      editorElements('.scrollableList:last').children('div.selectedOption').text("Select")
    })
    editorElements('.selectedOption').on('click', function (e) {
      e.stopPropagation()
      editorElements(this).next('ul').slideToggle(200)
      editorElements('.selectedOption').not(this).next('ul').hide()
    })
    editorElements('.scrollableList ul li').on('click', function (e) {
      let selectedLI, selectedLiId
      e.stopPropagation()
      selectedLI = editorElements(this).text()
      selectedLiId = editorElements(this).data('value')
      editorElements(this).parent().prev('.selectedOption').text(selectedLI)
      editorElements("#ldactnprop").show()
      editorElements(this).parent('ul').hide()
      editorElements(this).closest('.scrollableList').prev('.makeMeList').val(selectedLiId)
      if ((selectedLiId === 'slidein') || (selectedLiId === 'slideout') || (selectedLiId === 'chngtxt')) {
        editorElements('.effectFromWrapper').show()
        editorElements(".effectFromWrapper").show()
      } else if (editorElements(this).closest('.form-group').hasClass('effectFromWrapper')) {
        editorElements('.effectFromWrapper').show()
      } else {
        editorElements('.effectFromWrapper').hide()
        editorElements(".effectFromWrapper").hide()
      }
    })
    editorElements('.scrollableList').show()
    editorElements('.makeMeList').hide()
    if (editorElements(".selectedOption").html() == "Select") {
      editorElements("#ldactnprop").hide()
      editorElements('#addloadactn').hide()
    } else {
      editorElements("#ldactnprop").show()
      editorElements('#addloadactn').show()
    }
  }
