      ShowNavigate: getFlag(generated_slides[duplicate_slide_index].ShowNavigate, 1),
      SlideTransition: normalizeSlideTransition(generated_slides[duplicate_slide_index].SlideTransition),
      UseTransitionOnBack: getFlag(generated_slides[duplicate_slide_index].UseTransitionOnBack, 0),
      AutoNavigate: getFlag(generated_slides[duplicate_slide_index].AutoNavigate, 0),
