  deleteActions = function (anim_id, animationOnId) {
    let activeObj, activeObject
    activeObj = canvas.getActiveObject()
    if (editorElements("#prvatfile").attr("href") != undefined) {
      if (editorElements("#prvatfile").attr("href").includes("http:") || editorElements("#prvatfile").attr("href").includes("https:")) {
        editorElements("#prvatfile").attr("href", "")
        editorElements("#txtanimjslink").val("")
        editorElements("#atprv").hide()
        editorElements("#atupoad").show()
        editorElements(".divupat").show()
        editorElements('.addclickactn').show()
        editorElements('#uploaddocbtn').html("Click here to Upload.")
      } else {
        editorElements("#prvatfile").attr("href", "")
        editorElements("#atprv").hide()
        editorElements("#atupoad").show()
        editorElements(".divupat").show()
        editorElements('.addclickactn').show()
        editorElements('#uploaddocbtn').html("Click here to Upload.")
      }
    }
    activeObject = canvas.getActiveObject()
    if (activeObject != undefined) {
      if (activeObject.type == 'Textbox') {
        void activeObject.getSelectedText()
        activeObject.setSelectionStyles({
          underline: ''
        })
        activeObject.setSelectionStyles({
          fill: activeObject.fill
        })
      }
    }
    removeAutomationById(anim_id)
    getselobjprop()
    LoadTimeline()
    canvas.setActiveObject(activeObj)
    clickactionallocated = ''
    editorElements("#ldactnprop").hide()
    editorElements("#getaudeff").html("")
    editorElements("#divaudeff").show()
    editorElements("#uploadaudiobtneff").html("Click here to Upload.")
    editorElements("#lbltargetobject").html("")
    targetids = ""
  }

