  /* =========================================================================
     4) CLICK: #SharePropAll
     - Share a single object or group as a whole; expand only active selections.
     ========================================================================= */
  editorElements(document).on("click", "#SharePropAll", function () {
    let active, objs, IDs, Names
    active = canvas.getActiveObject() /* STAMP: 2026-09-07 - The toolbar routes ALL object types here. */

    objs = !active ? [] : String(active.type).toLowerCase() === "activeselection" ? active.getObjects() : [active]
    IDs = ""
    Names = "";
    (objs || []).forEach(function (o) {
      IDs += `${o.id || ""},`
      Names += `${o.name === undefined ? "NA" : o.name},`
    })
    if (IDs.length) IDs = IDs.substring(0, IDs.length - 1)
    if (Names.length) Names = Names.substring(0, Names.length - 1)
    resetShareSelectionState()
    setShareSelectionState({
      ids: IDs,
      names: Names,
      index: ""
    })
    openSlidesModal()
  })

