  /**
  * Select the specified canvas object and synchronize sidebar and canvas focus.
  * @param {*} objId Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  Selectobj = function (objId) {
    editorElements(".showsel").css("background", "#fff")
    editorElements(".showsel").css("color", "#000")
    editorElements(".showsel").find("a").css("color", "#000")
    editorElements(`#showsel_${objId}`).css("background", "#444")
    editorElements(`#showsel_${objId}`).css("color", "#fff")
    editorElements(`#showsel_${objId}`).find("a").css("color", "#fff")
    canvas.getObjects().forEach(function (o) {
      let divlen, contactTopPosition
      if (o.id === objId) {
        if ((CurrentSelObj == "") || (CurrentSelObj != objId)) {
          CurrentSelObj = objId
          divlen = editorElements(`#chkobj_${objId}`).length
          if (parseInt(divlen) > 0) {
            contactTopPosition = editorElements(`#div_${objId}`).position().top
            editorElements("#myObjnav").animate({
              scrollTop: contactTopPosition
            })
          }
          canvas.setActiveObject(o)
        }
      } else {
        editorElements(`#chkobj_${o.id}`).prop("checked", false)
      }
    })
  }

  /**
  * Discard the active canvas selection for the specified object context.
  * @param {*} objId Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  DeSelectobj = function (objId) {
    canvas.getObjects().forEach(function (o) {
      if (o.id === objId) {
        editorElements(`#showsel_${objId}`).css("background", "#fff")
        editorElements(`#showsel_${objId}`).css("color", "#000")
        editorElements(`#showsel_${objId}`).find("a").css("color", "#000")
        canvas.discardActiveObject()
      }
    })
  }
  editorElements(document).on("click", ".chkobjsel", function () {
    let objId, isGroupSelected, checked
    objId = editorElements(this).attr("id").replace("chkobj_", "")
    isshowarray = "0"
    editorElements(".trarray").hide()
    editorElements(".tblarrlist").css("background", "#808080")
    editorElements(".showarray").removeClass("fa fa-arrow-up")
    editorElements(".chkarr").hide()
    editorElements(".showarray").addClass("showarray fa fa-arrow-down")
    editorElements(".divlstarray").html("")
    editorElements(".tdgrparray").hide()
    selectedarray = "0"
    isGroupSelected = false
    checked = editorElements(this).prop("checked")
    if (checked) {
      canvas.getObjects().forEach(function (o) {
        if (o.id === objId) {
          editorElements(`#chkobj_${objId}`).prop("checked", true)
          if (o.type == "group") {
            isGroupSelected = true
            canvas.setActiveObject(o)
            return
          }
          canvas.setActiveObject(o)
        }
      })
      if (!isGroupSelected) {
        editorElements(`#tdgrparray_${objId}`).show()
      }
      makeObjectActive(objId)
    } else {
      void canvas.getActiveObject()
      editorElements(`#chkobj_${objId}`).prop("checked", false)
      canvas.discardActiveObject()
      canvas.requestRenderAll()
    }
  })
