  editorElements(document).on("click", ".updatearticulate", function () {
    let objId, anim_id, la_index, selected_obj_id, clickOnObjName, ac_index
    objId = editorElements(this).attr("id").replace("lbleffart_", "")
    canvas.getObjects().forEach(function (o) {
      if (o.id === objId) {
        canvas.setActiveObject(o)
      }
    })
    IsLoadAction = 1
    anim_id = editorElements(this).attr("name").replace("lbleffart_", "")
    la_index = slide_load_actions.findIndex(obj => obj.id === anim_id)
    slide_load_actions[la_index].effect = editorElements('#sel_load_effect').val()
    slide_load_actions[la_index].delay = editorElements('#load_delay').val()
    slide_load_actions[la_index].duration = editorElements('#dur_delay').val()
    slide_load_actions[la_index].articulate = editorElements(this).prop("checked")
    selected_obj_id = canvas.getActiveObject().id
    clickOnObjName = canvas.getActiveObject().type
    ac_index = animationOnControls.findIndex(obj => obj.id === selected_obj_id)
    animationOnControls[ac_index].effect = editorElements('#sel_load_effect').val()
    addActionToList(null, selected_obj_id, clickOnObjName, null, null, editorElements('#sel_load_effect').val(), null, null, null, null, null, editorElements('#load_delay').val(), '.loadActionList', anim_id, editorElements('#dur_delay').val(), null)
    editorElements('#addloadactn').hide()
    LoadTimeline()
  })

