  /* STAMP: 2026-09-29 - Keep undo-history persistence available to the
     automation handlers that intentionally live outside this bootstrap scope. */
  window.updateCanvasState = updateCanvasState = function () {
    let history, canvasAsJson
    if (ruConfig.isRestoring || ruConfig.undoStatus || ruConfig.redoStatus || !selected_slide_id) {
      return
    }
    history = ensureSlideHistoryState(selected_slide_id, getCanvasStateSnapshot())
    canvasAsJson = getCanvasStateSnapshot()
    if (history.currentStateIndex < (history.canvasState.length - 1)) {
      history.canvasState = history.canvasState.slice(0, history.currentStateIndex + 1)
    }
    if (history.canvasState[history.currentStateIndex] !== canvasAsJson) {
      history.canvasState.push(canvasAsJson)
      history.currentStateIndex = history.canvasState.length - 1
      if (history.canvasState.length > ruConfig.maxStatesPerSlide) {
        history.canvasState.splice(0, history.canvasState.length - ruConfig.maxStatesPerSlide)
        history.currentStateIndex = history.canvasState.length - 1
      }
    }
    refreshUndoRedoButtons(selected_slide_id)
  }
  /**
  * STAMP: 2026-09-05. Insert a revived library object through the existing
  * control, group, slide persistence and undo contracts as one undo step.
  */
  window.CGObjectLibraryEditor = {
    getSlideId() {
      return ruConfig.isRestoring ? null : selected_slide_id
    },
    insert(object, expectedSlideId) {
      if (ruConfig.isRestoring || !expectedSlideId || (selected_slide_id !== expectedSlideId)) {
        throw new Error("The active slide changed. Select Use object again.")
      }
      updateCanvasState()
      canvas.discardActiveObject()
      function register(item) {
        let children
        pushControl(item.id, item.type)
        if (item.type === "group") {
          children = item.getObjects()
          slide_groups.push({
            groupId: item.id,
            ObjectArray: children.map(function (child) {
              return child.id
            })
          })
          children.forEach(register)
        }
      }
      register(object)
      if (typeof window.applyCanvasObjectActionControls === "function") window.applyCanvasObjectActionControls(object)
      canvas.add(object)
      canvas.setActiveObject(object)
      object.setCoords()
      generated_slides[slide_index].groups = slide_groups
      generated_slides[slide_index].jsonobj = canvas.toObject(['id'])
      updateDropdownList()
      updateCanvasState()
      updateSlideThumbnail(selected_slide_id, canvas.toDataURL())
      canvas.requestRenderAll()
    },
    /* STAMP: 2026-09-26 - Insert independent component objects as one editor
       transaction, or replace one component without opening a generic group editor. */
    insertMany(objects, expectedSlideId, replaceObject) {
      let objectIds
      if (ruConfig.isRestoring || !expectedSlideId || (selected_slide_id !== expectedSlideId)) {
        throw new Error("The active slide changed. Add the markers again.")
      }
      if (!Array.isArray(objects) || !objects.length) throw new Error("No marker objects were created.")
      updateCanvasState()
      canvas.discardActiveObject()
      function objectTreeIds(item) {
        let ids
        ids = item && item.id ? [item.id] : []
        if (item && (item.type === "group") && (typeof item.getObjects === "function")) {
          item.getObjects().forEach(function (child) {
            ids = ids.concat(objectTreeIds(child))
          })
        }
        return ids
      }
      function unregister(item) {
        objectIds = objectTreeIds(item)
        slide_controls = slide_controls.filter(function (control) { return !objectIds.includes(control.id) })
        all_controls = all_controls.filter(function (control) { return !objectIds.includes(control.id) })
        slide_groups = slide_groups.filter(function (group) { return !objectIds.includes(group.groupId) })
        objectIds.forEach(function (id) {
          editorElements(`#sel_control option[value="${id}"]`).remove()
          editorElements(`#div_${id}`).remove()
        })
      }
      function register(item) {
        let children
        pushControl(item.id, item.type)
        if (item.type === "group") {
          children = item.getObjects()
          slide_groups.push({
            groupId: item.id,
            ObjectArray: children.map(function (child) { return child.id })
          })
          children.forEach(register)
        }
      }
      if (replaceObject) {
        unregister(replaceObject)
        canvas.remove(replaceObject)
      }
      objects.forEach(function (object) {
        register(object)
        if (typeof window.applyCanvasObjectActionControls === "function") window.applyCanvasObjectActionControls(object)
        canvas.add(object)
        object.setCoords()
      })
      canvas.setActiveObject(objects[objects.length - 1])
      generated_slides[slide_index].controls = slide_controls
      generated_slides[slide_index].groups = slide_groups
      generated_slides[slide_index].jsonobj = canvas.toObject(['id'])
      updateDropdownList()
      updateCanvasState()
      updateSlideThumbnail(selected_slide_id, canvas.toDataURL())
      canvas.requestRenderAll()
    }
  }

  /**
  * Apply hover and active state values to the relevant interactive objects.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  updateActiveStateObjects = function () {
    let ao, src_id, target_id, targetObj, srcObject
    ao = canvas.getActiveObject()
    if (editorElements("#cb_active_state").is(':checked')) {
      src_id = ao.get('id')
      target_id = src_id.replace('_hover', '')
    } else {
      src_id = ao.get('id')
      target_id = `${ao.get('id')}_hover`
    }
    targetObj = canvas.getObjectById(target_id)
    srcObject = canvas.getObjectById(src_id)
    if (targetObj && srcObject) {
      targetObj.scaleToWidth(srcObject.getScaledWidth())
      targetObj.scaleToHeight(srcObject.getScaledHeight())
      targetObj.set('scaleX', srcObject.scaleX)
      targetObj.set('scaleY', srcObject.scaleY)
      targetObj.set('top', srcObject.top)
      targetObj.set('left', srcObject.left)
      targetObj.setCoords()
      canvas.renderAll()
    }
  }

