  /* STAMP: 2026-08-26 - Quick Action hyperlink bridge.
   * Keeps the compact selection toolbar on the established slide action and
   * Fabric serialization paths so links remain editable in legacy panels. */
  window.CGObjectLinkEditor = {
    get(objectId, selection) {
      let hasSelectedText, action
      hasSelectedText = selection && selection.text && (selection.end > selection.start)
      action = slide_actions.find(function (entry) {
        if (!entry || (entry.actionFrom !== objectId) || (entry.function !== "Hyperlink") || entry.isDocument) return false
        if (!hasSelectedText) return !entry.selText
        return (entry.selText === selection.text) && (Number(entry.startIndex) === Number(selection.start)) && (Number(entry.endIndex) === Number(selection.end))
      })
      if (!action) return null
      return {
        url: action.actionTo || "",
        openInNewTab: (action.openInNewTab !== false) && (action.SelTab !== "SameTab"),
        followLink: action.followLink !== false
      }
    },
    save(objectId, values) {
      let slide, object, selection, hasSelectedText, action
      slide = generated_slides && generated_slides[slide_index]
      object = canvas && (typeof canvas.getObjectById === "function") ? canvas.getObjectById(objectId) : null
      if (!slide || !object || !values || !values.url) return false
      selection = values.selection
      hasSelectedText = selection && selection.text && (selection.end > selection.start)
      action = slide_actions.find(function (entry) {
        if (!entry || (entry.actionFrom !== objectId) || (entry.function !== "Hyperlink") || entry.isDocument) return false
        if (!hasSelectedText) return !entry.selText
        return (entry.selText === selection.text) && (Number(entry.startIndex) === Number(selection.start)) && (Number(entry.endIndex) === Number(selection.end))
      })
      if (!action) {
        action = {
          id: generate_id("ca_"),
          actionFrom: objectId,
          event: "click",
          function: "Hyperlink"
        }
        slide_actions.push(action)
      }
      action.actionTo = values.url
      action.SelTab = values.openInNewTab ? "NewTab" : "SameTab"
      action.openInNewTab = values.openInNewTab !== false
      action.followLink = values.followLink !== false
      action.isDocument = false
      if (["text", "textbox", "i-text"].indexOf(String(object.type).toLowerCase()) !== -1) {
        if (hasSelectedText && (typeof object.setSelectionStyles === "function")) {
          action.startIndex = selection.start
          action.endIndex = selection.end
          action.selText = selection.text
          object.setSelectionStyles({
            fill: "#1e01ff",
            underline: true
          }, selection.start, selection.end)
          slide_actions = slide_actions.filter(function (entry) {
            return (entry === action) || (entry.actionFrom !== objectId) || (entry.function !== "Hyperlink") || !!entry.selText
          })
        } else {
          delete action.startIndex
          delete action.endIndex
          delete action.selText
          object.set({
            fill: "#1e01ff",
            underline: true
          })
          slide_actions = slide_actions.filter(function (entry) {
            return (entry === action) || (entry.actionFrom !== objectId) || (entry.function !== "Hyperlink")
          })
        }
        object.setCoords()
      }
      slide.actions = slide_actions
      slide.jsonobj = canvas.toObject(["id"])
      slide.jsonobj.actions = slide_actions
      syncCurrentSlideAutomation(action.id)
      slide.svg = encodeURIComponent(canvas.toSVG())
      slide.imgprev = canvas.toDataURL()
      canvas.requestRenderAll()
      canvas.fire("object:modified", {
        target: object
      })
      LoadTimeline()
      if (typeof syncSelectedObjectAutomationPanel === "function") syncSelectedObjectAutomationPanel()
      updateCanvasState()
      return true
    }
  }
