  /**
  * Generated slide rail scroll enforcement stamped 2026-04-10.
  * Keeps the sortable slide list as a bounded viewport-driven scroll region
  * even when later theme or sortable rules clip the right-side panel.
  */
  function enforceGeneratedSlidesScroll() {
    let slideSection, generatedSlides, sectionRect, slidesRect, viewportHeight, availableHeight, sectionHeight
    slideSection = document.getElementById("slidesection")
    generatedSlides = document.querySelector("#slidesection .generatedSlides")
    if (!slideSection || !generatedSlides) {
      return
    }
    sectionRect = slideSection.getBoundingClientRect()
    slidesRect = generatedSlides.getBoundingClientRect()
    viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0
    availableHeight = Math.max(220, Math.floor(viewportHeight - slidesRect.top - 16))
    sectionHeight = Math.max(320, Math.floor(viewportHeight - sectionRect.top - 16))
    slideSection.style.setProperty("display", "flex", "important")
    slideSection.style.setProperty("flex-direction", "column", "important")
    slideSection.style.setProperty("min-height", "0", "important")
    slideSection.style.setProperty("height", `${sectionHeight}px`, "important")
    slideSection.style.setProperty("max-height", `${sectionHeight}px`, "important")
    slideSection.style.setProperty("overflow", "hidden", "important")
    generatedSlides.style.setProperty("display", "block", "important")
    generatedSlides.style.setProperty("flex", "1 1 auto", "important")
    generatedSlides.style.setProperty("min-height", "0", "important")
    generatedSlides.style.setProperty("height", `${availableHeight}px`, "important")
    generatedSlides.style.setProperty("max-height", `${availableHeight}px`, "important")
    generatedSlides.style.setProperty("overflow-x", "hidden", "important")
    generatedSlides.style.setProperty("overflow-y", "auto", "important")
    generatedSlides.style.setProperty("overscroll-behavior", "contain", "important")
  }
  window.setTimeout(enforceGeneratedSlidesScroll, 0)
  editorElements(window).on("resize orientationchange", function () {
    enforceGeneratedSlidesScroll()
  })
  editorElements(document).on("mouseenter click", "#slidebars, #slidesection, #slidesection .generatedSlides", function () {
    enforceGeneratedSlidesScroll()
  })
  editorElements(".generatedSlides").sortable({
    items: "> .sld",
    cancel: ".duplicateSlide, .slidesettings, .dltSlide, .clsname, .clsnav",
    distance: 8,
    tolerance: "pointer",
    start(event, ui) {
      dragStartSlideIndex = ui.item.index()
    },
    stop(event, ui) {
      let dropSlideIndex
      dropSlideIndex = ui.item.index()
      if ((dragStartSlideIndex === null) || (dropSlideIndex === dragStartSlideIndex)) {
        dragStartSlideIndex = null
        return
      }
      ChangeSLDOrder(dropSlideIndex, dragStartSlideIndex)
      dragStartSlideIndex = null
      enforceGeneratedSlidesScroll()
    }
  })
  /**
  * Update the displayed slide order label after a slide move operation.
  * @param {*} sid Runtime parameter preserved from the source implementation.
  * @param {*} fid Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  ChangeSLDOrder = function (sid, fid) {
    let targetIndex, sourceIndex, movedSlide
    targetIndex = parseInt(sid, 10)
    sourceIndex = parseInt(fid, 10)
    if (targetIndex === sourceIndex) return
    if (!Array.isArray(generated_slides)) return
    if (isNaN(targetIndex) || isNaN(sourceIndex)) return
    if (!generated_slides[sourceIndex] || (targetIndex < 0) || (targetIndex >= generated_slides.length)) return
    persistActiveSlideState()
    movedSlide = generated_slides.splice(sourceIndex, 1)[0]
    generated_slides.splice(targetIndex, 0, movedSlide)
    refreshSlideSortUi()
  }

