  document.getElementById('ImportFile').addEventListener("change", function (e) {
    let files
    files = Array.prototype.slice.call(e.target.files || [])
    if (!files.length) {
      resetImportFileInput()
      return
    }
    pendingImportFiles = files
    if (editorHasImportData()) {
      safeShowModal("confirmImportModal", "Are you sure you want to import this file? The current canvas data will be replaced.")
      return
    }
    processImportedFiles(pendingImportFiles)
  })
