  /**
  * Structured reference for check focus.
  * @param {*} order Runtime parameter preserved from the source implementation.
  * @returns {*} Value and side effects preserved from the source implementation.
  */
  function checkFocus(order) {
    let no
    if (editorElements(document.activeElement).attr("type") == "number") {
      if (order == "Plus") {
        no = parseInt(editorElements(document.activeElement).val()) + 1
        editorElements(document.activeElement).val(no)
      }
      if (order == "BigPlus") {
        no = parseInt(editorElements(document.activeElement).val()) + 5
        editorElements(document.activeElement).val(no)
      }
      if (order == "Minus") {
        no = parseInt(editorElements(document.activeElement).val()) - 1
        editorElements(document.activeElement).val(no)
      }
      if (order == "BigMinus") {
        no = parseInt(editorElements(document.activeElement).val()) - 5
        editorElements(document.activeElement).val(no)
      }
    }
  }
