  object = canvas.getObjects().find(function (candidate) {
    return candidate && (candidate.id === objectId)
  })
  dialog = document.getElementById("cgObjectPreviewDialog")
  image = document.getElementById("cgObjectPreviewImage")
  title = document.getElementById("cgObjectPreviewTitle")
