  progress = document.getElementById("cgLoaderProgress")
  progressBar = document.getElementById("cgLoaderProgressBar")
  percent = document.getElementById("cgLoaderPercent")
  status = document.getElementById("cgLoaderStatus")
  cgLoaderProgressValue = Math.max(0, Math.min(100, Math.round(value)))
  if (progress) progress.setAttribute("aria-valuenow", String(cgLoaderProgressValue))
  if (progressBar) progressBar.style.width = `${cgLoaderProgressValue}%`
  if (percent) percent.textContent = `${cgLoaderProgressValue}%`
