      start = fabric.util.transformPoint(new fabric.Point(line.x1, line.y1), transform)
      end = fabric.util.transformPoint(new fabric.Point(line.x2, line.y2), transform)
      length = Math.hypot(end.x - start.x, end.y - start.y)
      if (!length) return
      tickX = (-(end.y - start.y) / length) * 4
      tickY = ((end.x - start.x) / length) * 4
